        int contexts=0;for(var method:node.methods)for(var instruction:method.instructions.toArray())if(instruction instanceof MethodInsnNode call&&call.owner.equals(EssentialDeviceImageCallers.IMAGE)&&call.name.equals("configureTexture")){var getter=call.getPrevious();var usage=getter.getPrevious();var mips=usage.getPrevious();require(getter instanceof MethodInsnNode g&&g.name.equals("getBits")&&usage instanceof VarInsnNode u&&u.var==2&&mips instanceof VarInsnNode m&&m.var==6,"original mip/usage context");method.instructions.remove(getter);method.instructions.remove(usage);method.instructions.remove(mips);contexts++;}require(contexts==1,"one creation context");controls++;
